<?php
declare(strict_types=1);
require_once __DIR__.'/../config/config.php';
header('Content-Type: application/json; charset=utf-8');
if(!current_user()){http_response_code(401);echo json_encode(['ok'=>false,'message'=>'Please sign in.']);exit;}
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}
verify_csrf();$in=json_decode(file_get_contents('php://input'),true)??[];$message=trim((string)($in['message']??''));$lang=preg_replace('/[^a-z0-9-]/i','',(string)($in['language']??'en'));$level=substr((string)($in['level']??'A1'),0,10);$topic=substr(trim((string)($in['topic']??'Everyday conversation')),0,120);$cid=(int)($in['conversation_id']??0);
if($message===''||mb_strlen($message)>1500){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Message must be 1–1500 characters.']);exit;}
$pdo=db();
$rate=$pdo->prepare("SELECT COUNT(*) FROM ai_messages m JOIN ai_conversations c ON c.id=m.conversation_id WHERE c.user_id=? AND m.role='user' AND m.created_at >= (NOW() - INTERVAL 1 MINUTE)");$rate->execute([current_user()['id']]);if((int)$rate->fetchColumn()>=12){http_response_code(429);echo json_encode(['ok'=>false,'message'=>'Please pause for a moment before sending more messages.']);exit;}
if($cid){$q=$pdo->prepare('SELECT id FROM ai_conversations WHERE id=? AND user_id=?');$q->execute([$cid,current_user()['id']]);if(!$q->fetch()){$cid=0;}}
if(!$cid){$q=$pdo->prepare('INSERT INTO ai_conversations(user_id,language_code,level,topic) VALUES(?,?,?,?)');$q->execute([current_user()['id'],$lang,$level,$topic]);$cid=(int)$pdo->lastInsertId();}
$pdo->prepare("INSERT INTO ai_messages(conversation_id,role,content) VALUES(?,'user',?)")->execute([$cid,$message]);
$history=$pdo->prepare('SELECT role,content FROM ai_messages WHERE conversation_id=? ORDER BY id DESC LIMIT 12');$history->execute([$cid]);$msgs=array_reverse($history->fetchAll());
$answer='I am your practice partner. Try asking me a question about '.$topic.'. I can help you practise, but the AI service is not connected yet. Add your provider API key on the server to enable generated replies.';$aiConnected=false;$provider=getenv('LINGUAFREE_AI_API_URL')?:'https://api.openai.com/v1/chat/completions';$key=getenv('LINGUAFREE_AI_API_KEY')?:'';$model=getenv('LINGUAFREE_AI_MODEL')?:'gpt-4o-mini';
if($key!==''&&function_exists('curl_init')){$payload=['model'=>$model,'temperature'=>0.6,'messages'=>array_merge([['role'=>'system','content'=>'You are LinguaFree, a kind expert language conversation tutor. Teach the learner in '.$lang.'. Learner level: '.$level.'. Topic: '.$topic.'. Reply naturally in the target language, then add a short correction and one useful alternative phrase when helpful. Keep replies concise, encouraging, safe, and suitable for learners. Do not claim to assess audio when only text is provided.']],$msgs)];$ch=curl_init($provider);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$key],CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_TIMEOUT=>35]);$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$data=json_decode((string)$raw,true);if($status>=200&&$status<300&&isset($data['choices'][0]['message']['content'])){$answer=(string)$data['choices'][0]['message']['content'];$aiConnected=true;}else error_log('LinguaFree AI provider returned HTTP '.$status.'.');}
$pdo->prepare("INSERT INTO ai_messages(conversation_id,role,content) VALUES(?,'assistant',?)")->execute([$cid,$answer]);echo json_encode(['ok'=>true,'conversation_id'=>$cid,'reply'=>$answer,'ai_connected'=>$aiConnected]);
